// Sanitizing power index — record JAH-GGN-UVSANITIZER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"uvc_mw": 2000, "capacity_l": 2, "price_usd": 60};
var value = (m.uvc_mw*m.capacity_l/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-UVSANITIZER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-UVSANITIZER-000001|' + value.toFixed(2) + ' sanitizing index');

